) as v(city_slug, slug, g)
where d.city_slug = v.city_slug and d.slug = v.slug;

do $$
begin
  if exists (select 1 from public.districts where geom is null or extensions.ST_IsEmpty(geom)) then
    raise exception 'district without a boundary: %',
      (select string_agg(city_slug || '/' || slug, ', ') from public.districts
        where geom is null or extensions.ST_IsEmpty(geom));
  end if;
end $$;

alter table public.districts alter column geom set not null;
create index districts_geom_idx on public.districts using gist (geom);

-- Keep `select *` on districts cheap for clients: the polygons are ~2 MB.
revoke select on public.districts from anon, authenticated;
grant select (city_slug, slug, city, name) on public.districts to authenticated;

-- Aliases only existed to map geocoder names onto districts.
drop table public.district_aliases;

-- ------------------------------------------------------- set_location v3
drop function public.set_location(double precision, double precision, text, text);

create function public.set_location(p_lat double precision, p_lng double precision)
returns public.neighborhoods
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_pt geometry;
  d public.districts;
  nb public.neighborhoods;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not exists (select 1 from public.profiles where id = auth.uid()) then
    raise exception 'profile required';
  end if;
  if p_lat is null or p_lng is null
     or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'invalid coordinates' using errcode = '22023';
  end if;

  v_pt := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326);

  select * into d from public.districts where ST_Covers(geom, v_pt) limit 1;

  -- GPS jitter on the shoreline, or a ferry close to the coast: take the
  -- nearest district within 1 km. (0.02° prefilter is > 1 km at these latitudes.)
  if not found then
    select * into d from public.districts
      where ST_DWithin(geom, v_pt, 0.02)
        and ST_DWithin(geom::geography, v_pt::geography, 1000)
      order by ST_Distance(geom::geography, v_pt::geography)
      limit 1;
  end if;

  if not found then
    raise exception 'outside supported districts' using errcode = 'P0004';
  end if;

  insert into public.neighborhoods (city, district, name, slug)
  values (d.city, d.name, d.name, d.city_slug || '/' || d.slug)
  on conflict (slug) do update set city = excluded.city
  returning * into nb;

  insert into public.user_locations (user_id, neighborhood_id, lat, lng, updated_at)
  values (auth.uid(), nb.id, p_lat, p_lng, now())
  on conflict (user_id) do update
    set neighborhood_id = excluded.neighborhood_id,
        lat = excluded.lat, lng = excluded.lng, updated_at = now();

  return nb;
end $$;
